<?php
require __DIR__.'/_common.php'; admin_require(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)$_POST['id'];$p=(string)$_POST['payment_status'];$d=(string)$_POST['delivery_status'];$allowedP=['pending','paid','failed','cancelled'];$allowedD=['pending','processing','delivered','failed'];if(in_array($p,$allowedP,true)&&in_array($d,$allowedD,true)){$pdo->prepare('UPDATE orders SET payment_status=?,delivery_status=? WHERE id=?')->execute([$p,$d,$id]);flash('Commande mise à jour');}redirect_self();}$rows=$pdo->query('SELECT o.*,p.name product,g.name game FROM orders o JOIN products p ON p.id=o.product_id JOIN games g ON g.id=p.game_id ORDER BY o.id DESC LIMIT 300')->fetchAll();admin_layout_start('Commandes');echo '<table><tr><th>N°</th><th>Client</th><th>Produit</th><th>Montant</th><th>Paiement</th><th>Livraison</th><th>Action</th></tr>';foreach($rows as $r){echo '<tr><td>'.h($r['order_number']).'</td><td>'.h($r['customer_email']??'').'</td><td>'.h($r['game'].' / '.$r['product']).'</td><td>'.h($r['amount'].' '.$r['currency']).'</td><td>'.h($r['payment_status']).'</td><td>'.h($r['delivery_status']).'</td><td><form method="post"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="id" value="'.h($r['id']).'"><select name="payment_status"><option '.($r['payment_status']==='pending'?'selected':'').'>pending</option><option '.($r['payment_status']==='paid'?'selected':'').'>paid</option><option '.($r['payment_status']==='failed'?'selected':'').'>failed</option><option '.($r['payment_status']==='cancelled'?'selected':'').'>cancelled</option></select><select name="delivery_status"><option '.($r['delivery_status']==='pending'?'selected':'').'>pending</option><option '.($r['delivery_status']==='processing'?'selected':'').'>processing</option><option '.($r['delivery_status']==='delivered'?'selected':'').'>delivered</option><option '.($r['delivery_status']==='failed'?'selected':'').'>failed</option></select><button>Mettre à jour</button></form></td></tr>';}echo '</table>';admin_layout_end();